#!/bin/bash
set -e

pushd libsignal

LIBSIGNAL_TAG=$(git describe --tags --always)
LIBSIGNAL_VERSION_FUNC=$(echo $LIBSIGNAL_TAG | tr -d 'v' | sed 's/\./_/g')

popd

cat > signalversion/version.go <<EOF
// Generated by update-ffi.sh; DO NOT EDIT.

package signalversion

const Version = "${LIBSIGNAL_TAG}"
EOF

cat > version.go <<EOF
// Generated by update-ffi.sh; DO NOT EDIT.

package libsignalgo

/*
#include "./libsignal-ffi.h"
*/
import "C"

func init() {
	// Compile time check to ensure the libsignal version matches
	C.signal_ffi_version_${LIBSIGNAL_VERSION_FUNC}()
}
EOF
